                idx = idx + 1
                let lv = l.getValue()
                let rv = right.getOrThrow().getValue()
                if (lv == rv) {
                    return idx
                }
                right = left
                var p: ?LinkedListNode<Int64> = None
                var c: ?LinkedListNode<Int64> = q.firstNode
