func fix(q: LinkedList<Int64>, cursor: ?LinkedListNode<Int64>, t: Int64): Int64 {
    if (q.isEmpty()) {
        return -81
    }
    match (cursor) {
        case Some(node) =>
            let next = q.forward(node).iterator()
            match (next.next()) {
                case Some(value) =>
                    q.addAfter(node, t)
                    return value
                case None =>
                    return -81
            }
        case None =>
            return -81
    }
}

main() {
    let q0 = LinkedList<Int64>([8, 3, 6, 1])
    let r0 = fix(q0, q0.nodeAt(1), 2)
    println(r0 == 6 && q0.toArray() == [8, 3, 6, 2, 1])
    let q1 = LinkedList<Int64>([5, 5, -3, 9])
    let r1 = fix(q1, q1.nodeAt(2), 3)
    println(r1 == 9 && q1.toArray() == [5, 5, -3, 9, 3])
}

