func fix(q: LinkedList<Int64>, cursor: ?LinkedListNode<Int64>, t: Int64): Int64 {
    if (q.isEmpty()) {
        return -81
    }
    match (cursor) {
        case Some(node) =>
            var prev: ?LinkedListNode<Int64> = None
            var cur: ?LinkedListNode<Int64> = q.firstNode
            while (let Some(c) <- cur) {
                if (c == node) {
                    break
                }
                prev = cur
                cur = None
                // 需要获取下一个节点，但 LinkedListNode 没有 next 属性，
                // 使用 forward 迭代器来定位前一个节点
                break
            }
            // 使用 forward 迭代器遍历，找到 cursor 的前一个节点
            var it = q.forward(q.firstNode.getOrThrow())
            var previous: ?LinkedListNode<Int64> = None
            var found = false
            while (true) {
                match (it.next()) {
                    case Some(n) =>
                        if (n == node) {
                            found = true
                            break
