{"code":"import std.collection.*

func repair(q: LinkedList<Int64>, offset: Int64, t: Int64): Int64 {
    if (q.isEmpty()) {
        return 0
    }
    if (offset < 0 || offset >= q.size) {
        return 0
    }
    let startNode = q.nodeAt(offset)
    match (startNode) {
        case Some(node) =>
            var count: Int64 = 0
            var it = q.forward(node)
            // 跳过标记本身
            if (it.next().isSome()) {
                while (true) {
                    match (it.next()) {
                        case Some(v) =>
                            if (v == t) {
                                break
                            }
                            if (v < 0) {
                                // 需要修改该节点，但迭代器只给值，需通过节点操作
                                // 使用 nodeAt 定位并修改
                                count++
                            }
                        case None => break
                    }
                }
            }
            // 由于迭代器无法直接修改，重新遍历节点进行修改
            if (count > 0) {
                var idx = offset + 1
                var modified: Int64 = 0
                while (idx < q.size) {
                    let optNode = q.nodeAt(idx)
                    match (optNode) {
                        case Some(n) =>
                            let val = n.value
                            if (val == t) {
                                break
                            }
                            if (val < 0) {
                                n.value = -val
                                modified++
                            }
