func repair(q: LinkedList<Int64>, offset: Int64, t: Int64): Int64 {
    if (q.isEmpty()) {
        return 0
    }
    if (offset < 0 || offset >= q.size) {
        return 0
    }
    let markOpt = q.nodeAt(offset)
    if (markOpt.isNone()) {
        return 0
    }
    let mark = markOpt.getOrThrow()
    var count: Int64 = 0
    var it = q.backward(mark)
    while (count < 2) {
        match (it.next()) {
            case Some(v) =>
                if (v % 2 != 0) {
                    let nodeOpt = q.nodeAt(offset)
                    // 需要定位到当前节点进行修改，改用遍历节点方式
                    count++
                }
            case None => break
        }
    }
    // 重新实现：通过节点遍历修改
    count = 0
    var curOpt = q.nodeAt(offset)
    if (curOpt.isNone()) {
        return 0
    }
    var cur = curOpt.getOrThrow()
    // 从标记的前一个节点开始向左
    var prevOpt = q.nodeAt(offset - 1)
    while (count < 2 && prevOpt.isSome()) {
        let node = prevOpt.getOrThrow()
        let val = node.value
        if (val % 2 != 0) {
            node.value = val + t
