    // 使用索引方式从 offset-1 向左遍历
    count = 0
    var i = offset - 1
    while (i >= 0 && count < 2) {
        let nodeOpt = q.nodeAt(i)
        if (nodeOpt.isNone()) {
            break
        }
        let node = nodeOpt.getOrThrow()
        let val = node.value
        if (val % 2 != 0) {
            node.value = val + t
            count++
        }
        i--
    }
    return count
}

