func repair(q: LinkedList<Int64>, offset: Int64, t: Int64): Int64 {
    if (q.isEmpty()) {
        return -999
    }
    var count: Int64 = 0
    var node = q.firstNode
    while (let Some(n) <- node) {
        let v = n.value
        if (v == t) {
            break
        }
        if (v < 0) {
            n.value = -v
            count++
        }
        node = n.next
    }
    return count
}

main() {
    let q0 = LinkedList<Int64>([5, -2, -2, 6, 3])
    let r0 = repair(q0, 3, 2)
    println(r0 == 2 && q0.toArray() == [5, 2, 2, 6, 3])
    let q1 = LinkedList<Int64>([3, 1, 4, 4, -3])
    let r1 = repair(q1, 1, 4)
    println(r1 == 0 && q1.toArray() == [3, 1, 4, 4, -3])
}

