func repair(q: LinkedList<Int64>, offset: Int64, t: Int64): Int64 {
    if (q.isEmpty()) {
        return -999
    }
    if (offset < 0 || offset >= q.size) {
        return -91
    }
    var mark = q.nodeAt(offset).getOrThrow()
    var it = q.backward(mark)
    while (true) {
        match (it.next()) {
            case Some(v) =>
                if (v > t) {
                    q.addBefore(mark, t - 1)
                    return v
                }
                mark = mark.prev.getOrThrow()
            case None => return -91
        }
    }
    return -91
}

