func fix(q: LinkedList<Int64>, cursor: ?LinkedListNode<Int64>, t: Int64): Int64 {
    if (t <= 0) {
        return 0
    }
    var node: ?LinkedListNode<Int64> = match (cursor) {
        case Some(c) => c.next
        case None => None
    }
    var sum: Int64 = 0
    var k: Int64 = 1
    var count: Int64 = 0
    while (count < t) {
        match (node) {
            case Some(n) =>
                sum += n.value * k
                k += 1
                count += 1
                node = n.next
            case None =>
                count = t
        }
    }
    return sum
}

