    var k: Int64 = 1
    var count: Int64 = 0
    var it = q.forward(node)
    while (count < t) {
        match (it.next()) {
            case Some(v) =>
                sum += v * k
                k += 1
                count += 1
            case None => break
        }
    }
    return sum
}

