import std.collection.*

func processEntry(q: LinkedList<Int64>, t: Int64): Int64 {
    if (t <= 0) {
        return 0
    }
    var sum: Int64 = 0
    var weight: Int64 = 1
    var count: Int64 = 0
    while (count < t && !q.isEmpty()) {
        let v = q.removeLast()
        match (v) {
            case Some(x) =>
                sum += x * weight
                weight += 1
                count += 1
            case None => break
        }
    }
    return sum
}

main() {
    let c0 = LinkedList<Int64>()
    c0.addLast(4)
    c0.addLast(-2)
    c0.addLast(7)
    let r0 = processEntry(c0, 1)
    println(r0 == 7 && c0.toArray() == [4, -2])
    let c1 = LinkedList<Int64>()
    c1.addLast(1)
    c1.addLast(6)
    let r1 = processEntry(c1, 2)
    println(r1 == 8 && c1.toArray() == Array<Int64>())
